42	#ifndef SG_INLINE_PTX_PTX_INT8_STOCHASTIC_ROUND
43	#define SG_INLINE_PTX_PTX_INT8_STOCHASTIC_ROUND
44	// Stochastic rounding with PTX prmt (permute bytes) for fast bit extraction.
45	// Replaces the hash_prng shift+multiply chain with a single PTX instruction
46	// for extracting the random threshold from the hash output.
47	__device__ __forceinline__ int8_t ptx_int8_stochastic_round(
48	    float val, float scale, unsigned rand_bits
49	) {
50	    float scaled = val / fmaxf(scale, 1e-12f);
51	    float tr = truncf(scaled);
52	    float frac = fabsf(scaled - tr);
53	    // Extract lower 16 bits as threshold using prmt
54	    unsigned lo16;
55	    asm("prmt.b32 %0, %1, 0, 0x4140;" : "=r"(lo16) : "r"(rand_bits));
56	    float threshold = (float)lo16 / 65536.0f;
57	    if (frac > threshold) tr += (scaled > 0) ? 1.0f : -1.0f;
58	    return (int8_t)fmaxf(-127.0f, fminf(127.0f, tr));
59	}
60	#endif  // SG_INLINE_PTX_PTX_INT8_STOCHASTIC_ROUND
61	#endif  // GROK_CUDA
