100	// FP32 vec4 fast path: float4 global traffic, canonical step CALLED 4×.
101	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_GROKADAMW_MIN_BLOCKS)
102	grokadamw_kernel_vec4_fp32(
103	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4, float4* ema4,
104	    const float4* grad4,
105	    float alpha, float lamb,
106	    float lr, float beta1, float beta2, float eps, float wd,
107	    float bc1, float bc2, int64_t N4
108	) {
109	    const int64_t stride = prim::grid_stride();
110	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
111	        float4 p = prim::ld_f32v4(param4 + i);
112	        float4 m = prim::ld_f32v4(exp_avg4 + i);
113	        float4 v = prim::ld_f32v4(exp_avg_sq4 + i);
114	        float4 e = prim::ld_f32v4(ema4 + i);
115	        float4 g = prim::ldg_f32v4(grad4 + i);
116	        ::grokking::sm90::sg_sanitize_grad4(g);
117	        #pragma unroll
118	        for (int u = 0; u < 4; ++u) {
119	            grokadamw_step(&p.x, &m.x, &v.x, &e.x, &g.x,
120	                           alpha, lamb, lr, beta1, beta2, eps, wd,
121	                           bc1, bc2, u);
122	        }
123	        prim::st_f32v4(param4 + i, p);
124	        prim::st_f32v4(exp_avg4 + i, m);
125	        prim::st_f32v4(exp_avg_sq4 + i, v);
126	        prim::st_f32v4(ema4 + i, e);
127	    }
128	}
