266	void launch_fused_grokadamw_step_q3(
267	    torch::Tensor param,
268	    torch::Tensor exp_avg_int8, torch::Tensor exp_avg_scales,
269	    torch::Tensor exp_avg_sq_bf16, torch::Tensor ema_bf16,
270	    torch::Tensor grad,
271	    float alpha, float lamb,
272	    float beta1, float beta2,
273	    float lr, float weight_decay, float eps,
274	    float bc1, float bc2, unsigned global_step
275	) {
276	    const int64_t N = param.numel();
277	    if (N == 0) return;
278	
279	    auto stream = at::cuda::getCurrentCUDAStream().stream();
280	    const int block = SG_TUNED_BLOCK_SIZE;
281	    const int grid = static_cast<int>(
282	        std::min<int64_t>(65535, (N + block - 1) / block));
283	    const int q_block_size = std::max<int>(1,
284	        static_cast<int>(N / exp_avg_scales.numel()));
285	
286	    AT_DISPATCH_FLOATING_TYPES_AND2(
287	        at::ScalarType::Half, at::ScalarType::BFloat16,
288	        param.scalar_type(), "grokadamw_q3", [&] {
289	            grokadamw_q3_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
290	                param.data_ptr<scalar_t>(),
291	                exp_avg_int8.data_ptr<int8_t>(),
292	                exp_avg_scales.data_ptr<float>(),
293	                reinterpret_cast<__nv_bfloat16*>(exp_avg_sq_bf16.data_ptr()),
294	                reinterpret_cast<__nv_bfloat16*>(ema_bf16.data_ptr()),
295	                grad.data_ptr<scalar_t>(),
296	                alpha, lamb, lr, beta1, beta2, eps, weight_decay,
297	                bc1, bc2, global_step, N, q_block_size);
298	            SG_LAUNCH_CHECK(stream);
299	        });
300	}
