321	// AdamW is GrokAdamW with lamb=0 (EMA amplification disabled).
322	// The ema buffer is not needed; allocate a dummy per-tensor.
323	void launch_fused_adamw_simple(
324	    std::vector<torch::Tensor>& params,
325	    std::vector<torch::Tensor>& exp_avgs,
326	    std::vector<torch::Tensor>& exp_avg_sqs,
327	    std::vector<torch::Tensor>& grads,
328	    std::vector<int64_t>& steps,
329	    float beta1, float beta2, float lr, float wd, float eps
330	) {
331	    for (size_t t = 0; t < params.size(); t++) {
332	        const int64_t N = params[t].numel();
333	        if (N == 0 || !grads[t].defined()) continue;
334	        float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[t]));
335	        float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[t]));
336	        auto ema_dummy = torch::zeros_like(exp_avgs[t]);
337	        launch_grokadamw_step(params[t], exp_avgs[t], exp_avg_sqs[t],
338	                              ema_dummy, grads[t],
339	                              0.0f, 0.0f, lr, beta1, beta2, eps, wd,
340	                              bc1, bc2);
341	    }
