16	// Defensive bias-correction denominator guard. bc = 1 - beta^t; at t==0 bc==0
17	// which divides by zero. The host contract is step>=1 so this never fires in
18	// normal operation; the guard is free (one fmaxf) and prevents silent NaN
19	// poisoning if a caller ever violates the contract.
20	__device__ __forceinline__ float sg_safe_bc(float bc) {
21	    return fmaxf(bc, 1e-30f);
22	}
