30	// ═══════════════════════════════════════════════════════════════════════
31	//  Warp-level reduction helper
32	//
33	//  Sum a float across d_inner threads (all in one warp, d_inner ≤ WARP_SIZE).
34	//  Uses platform-abstracted shuffle; works for any d_inner ≤ WARP_SIZE
35	//  (including non-power-of-2).
36	// ═══════════════════════════════════════════════════════════════════════
37	
38	__device__ __forceinline__ float warp_reduce_sum(float val, int d_inner, int tid) {
39	    unsigned mask = (d_inner < WARP_SIZE) ? ((1u << d_inner) - 1) : FULL_WARP_MASK;
40	    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
41	        float other = SHFL_DOWN_SYNC(mask, val, offset);
42	        if (tid + offset < d_inner)
43	            val += other;
44	    }
45	    return val;  // only lane 0 has the correct sum
46	}
