48	// ═══════════════════════════════════════════════════════════════════════
49	//  Stochastic Rounding for Quantized Optimizer States (Config 3)
50	//
51	//  Hash-based PRNG: deterministic per (step, element) pair, no state needed.
52	//  Faster than cuRAND, no separate state tensor required.
53	// ═══════════════════════════════════════════════════════════════════════
54	
55	// Hash-based PRNG (Philox-like): deterministic, no state
56	__device__ __forceinline__ unsigned hash_prng(unsigned step, unsigned idx) {
57	    unsigned h = (step * 2654435761u) ^ (idx * 2246822519u);
58	    h ^= h >> 16;
59	    h *= 0x45d9f3bu;
60	    h ^= h >> 16;
61	    return h;
62	}
