66	// BF16 stochastic rounding: unbiased quantization
67	__device__ __forceinline__ __nv_bfloat16 float_to_bf16_stochastic(float val, unsigned rand_bits) {
68	    unsigned bits = __float_as_uint(val);
69	    unsigned truncated = bits & 0xFFFF;     // bits that BF16 drops
70	    unsigned threshold = rand_bits & 0xFFFF; // random 16-bit threshold
71	    if (truncated > threshold) {
72	        bits += 0x10000;  // round up
73	    }
74	    bits &= 0xFFFF0000;  // truncate to BF16
75	    return __float2bfloat16(__uint_as_float(bits));
76	}
