78	// INT8 per-block quantization with stochastic rounding
79	// block_size elements share one FP32 scale factor
80	__device__ __forceinline__ int8_t float_to_int8_stochastic(
81	    float val, float scale, unsigned rand_bits
82	) {
83	    float scaled = val / scale;
84	    float truncated = truncf(scaled);
85	    float frac = fabsf(scaled - truncated);
86	    float threshold = (float)(rand_bits & 0xFFFF) / 65536.0f;
87	    if (frac > threshold) {
88	        truncated += (scaled > 0) ? 1.0f : -1.0f;
89	    }
90	    return (int8_t)fmaxf(-127.0f, fminf(127.0f, truncated));
91	}
