34	// =========================================================================
35	//  Post-launch error check (usable from any .cu launcher).
36	//
37	//  SG_LAUNCH_CHECK(stream) is called immediately AFTER a kernel launch. It
38	//  reads cudaGetLastError() to surface a launch-time failure (bad launch
39	//  config, too much shared mem, invalid args) and TORCH_CHECKs it — turning a
40	//  silent async error into an immediate, attributable exception.
41	//
42	//  In release (default) it is launch-error-only: NO synchronize, so the hot
43	//  path keeps its async overlap. Define SG_LAUNCH_CHECK_SYNC=1 (debug builds)
44	//  to additionally cudaStreamSynchronize and catch errors raised during kernel
45	//  EXECUTION (illegal address, etc.) at the launch site instead of later.
46	//
47	//  Macro (not a function) so __FILE__/__LINE__ point at the launch site and so
48	//  it is a no-op-safe statement usable inside any control flow. The
49	//  do{...}while(0) wrapper makes it a single statement that needs a trailing ;.
50	// =========================================================================
51	#ifndef SG_LAUNCH_CHECK_SYNC
52	#define SG_LAUNCH_CHECK_SYNC 0
53	#endif
54	
55	#if SG_LAUNCH_CHECK_SYNC
56	#define SG_LAUNCH_CHECK(stream)                                               \
57	    do {                                                                      \
58	        cudaError_t _sg_launch_err = cudaGetLastError();                      \
59	        TORCH_CHECK(_sg_launch_err == cudaSuccess,                            \
60	                    "CUDA kernel launch failed: ",                            \
61	                    cudaGetErrorString(_sg_launch_err));                      \
62	        cudaError_t _sg_sync_err = cudaStreamSynchronize(stream);             \
63	        TORCH_CHECK(_sg_sync_err == cudaSuccess,                              \
64	                    "CUDA kernel execution failed: ",                         \
65	                    cudaGetErrorString(_sg_sync_err));                        \
66	    } while (0)
67	#else
68	#define SG_LAUNCH_CHECK(stream)                                               \
69	    do {                                                                      \
70	        (void)(stream);                                                       \
71	        cudaError_t _sg_launch_err = cudaGetLastError();                      \
72	        TORCH_CHECK(_sg_launch_err == cudaSuccess,                            \
73	                    "CUDA kernel launch failed: ",                            \
74	                    cudaGetErrorString(_sg_launch_err));                      \
75	    } while (0)
76	#endif
