329	// =========================================================================
330	//  Adam denominator helpers.
331	//
332	//  adam_denom_add(v, eps) is the additive denominator sqrtf(v)+eps that you
333	//  DIVIDE by (m_hat / denom). It matches the canonical algorithms/<opt>.h
334	//  math exactly. (Previously this file shipped a single `adam_denom_fast`
335	//  whose comment claimed "fast rsqrt + Newton-Raphson" but whose body was
336	//  plain `sqrtf(v)+eps` — the comment was wrong; it is corrected and renamed
337	//  here. There are no in-tree callers of either name, so nothing breaks.)
338	//
339	//  adam_recip_denom_fast(v, eps) is the genuine fast path: the RECIPROCAL of
340	//  the denominator, 1/(sqrt(v)+eps), computed via the hardware approximate
341	//  reciprocal-sqrt (__frsqrt_rn) so the apply becomes a MULTIPLY (m_hat *
342	//  recip) instead of a divide. It returns the reciprocal, so callers must
343	//  multiply, not divide. Equivalent to 1.0f/(sqrtf(v)+eps) to within the
344	//  rsqrt approximation; do NOT use it on the bit-stability path — it is for
345	//  the perf-tolerant fast denom only.
346	// =========================================================================
347	
348	__device__ __forceinline__ float adam_denom_add(float v, float eps) {
349	    return sqrtf(v) + eps;
350	}
351	
352	__device__ __forceinline__ float adam_recip_denom_fast(float v, float eps) {
353	    // sqrt(v) = v * rsqrt(v); guard v==0 so rsqrt(0)=+inf does not poison the
354	    // result (then denom = eps, recip = 1/eps).
355	    const float rs = __frsqrt_rn(v);
356	    const float sqrt_v = (v > 0.0f) ? (v * rs) : 0.0f;
357	    return 1.0f / (sqrt_v + eps);
358	}
